"""Reproducible municipality coverage matrix and tested developer manifest."""
import csv,json,html,collections,datetime
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(n):return json.loads((ROOT/'data'/n).read_text())
def e(x):return html.escape(str(x),quote=True)
def main():
 rows=read('source-live-tests.json');sources=read('sources.json');intake=read('intake-report.json');inventory=read('municipal-source-inventory.json');out=ROOT/'static/source-audit';out.mkdir(exist_ok=True)
 results={r['source']:r for r in intake['sources']};feeds=[s for s in sources if s.get('feed')];counts=collections.Counter(r['crawlTest'] for r in rows)
 topics=sorted({t for r in rows for t in r['topics']});matrix=[]
 for municipality in inventory:
  slug=municipality['municipality'];local=[r for r in rows if slug in r['municipalities']];linked=[s for s in feeds if slug in s.get('coverageCandidates',[]) or s.get('municipality')==slug]
  matrix.append(dict(municipality=slug,routes=len(local),accessible=sum(r['crawlTest']=='page_accessible' for r in local),configuredFeeds=len(linked),topics={t:sum(t in r['topics'] and r['crawlTest']=='page_accessible' for r in local) for t in topics},sourceUrls=[r['url'] for r in local]))
 manifest={'generatedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'26 Utrechtse gemeenten; gecontroleerde inventaris, geen garantie op volledige nieuwsdekking','autoPublish':False,'sources':[dict(id=s['id'],name=s['name'],feed=s['feed'],coverageCandidates=s.get('coverageCandidates',[]),municipality=s.get('municipality'),articleHosts=s.get('articleHosts',[]),mode='signal_only',lastTest=results.get(s['id']),suggestedPollMinutes=15,imageRights='unknown_unless_separately_verified') for s in feeds],'municipalities':matrix,'unconnectedRoutes':[r for r in rows if r['url'] not in {s.get('url') for s in feeds}],'publicationContract':{'required':['source identity','source publication date','verified municipality','facts traceable to source','deduplication','own concise text','image rights or approved fallback','expiry for alerts'],'hold':['unverified accusations','personal details of minors or victims','unknown location','missing body or access challenge','proposals described as decisions','expired alerts'],'note':'Contract voor ontwikkelaar; nog geen autonome schrijf- en publicatieservice geïmplementeerd.'}}
 (ROOT/'data/developer-source-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2));(out/'developer-source-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
 with (out/'gemeentelijke-bronnen.csv').open('w',newline='') as f:
  w=csv.writer(f);w.writerow(['gemeenten','onderwerpen','bron','url','test','controle','feeds'])
  for r in rows:w.writerow(['; '.join(r['municipalities']),'; '.join(r['topics']),r['name'],r['url'],r['crawlTest'],r['checkedAt'],'; '.join(r['feedCandidates'])])
 body='<header><p>PITO · brononderzoek & techniek</p><h1>Elke gemeente, iedere bronstap in beeld</h1><p>Live controle op 13 oktober 2026. Een bereikbare pagina is geen geteste artikelcrawler. Een feed levert signalen, geen toestemming om teksten of beelden over te nemen.</p></header>'
 body+='<nav><a href="#gemeenten">26 gemeenten</a><a href="#feeds">Werkende aanvoer</a><a href="#developer">Developer</a><a href="gemeentelijke-bronnen.csv">Bronnenlijst CSV</a><a href="developer-source-manifest.json">Manifest JSON</a><a href="verwerking.html">Verwerkingswachtrij</a></nav>'
 body+='<section class="stats">'+''.join('<div><strong>'+str(v)+'</strong><span>'+label+'</span></div>' for v,label in [(len(rows),'unieke routes getest'),(counts['page_accessible'],'pagina’s toegankelijk'),(len(feeds),'feeds geconfigureerd'),(sum(r['status']=='ok' for r in intake['sources']),'feeds succesvol in laatste run')])+'</section>'
 body+='<h2>Waarom er minder artikelen staan dan signalen</h2><p>Feeds zijn korte vensters op recente publicaties; ze vormen geen volledig archief. Andere websites hebben eigen verslaggevers, interviews, tips en exclusieve informatie. Meer bronnen verkleinen de gaten, maar leveren niet automatisch al hun journalistieke werk op. Onze lees- en schrijfverwerking is nog een afzonderlijke stap.</p><p>Handmatig aangedragen links krijgen direct aandacht. Berichten uit de algemene aanvoer wachten nog op tekstextractie, plaatsbepaling en verwerking. Die wachtrij moet de developer continu laten afwerken; alleen vaker RSS ophalen lost dit niet op.</p>'
 body+='<h2 id="gemeenten">Dekking per gemeente</h2><p>Getallen per onderwerp zijn bereikbare bronroutes, geen aantallen nieuwsberichten of actieve crawlers. Nul is een onderzoeksgat. Sommige categorieën bevatten algemene gemeentelijke informatie; directe verenigings- en organisatiesites blijven nodig.</p><div class="table"><table><thead><tr><th>Gemeente</th><th>Getest</th><th>Feeds*</th>'+''.join('<th>'+e(t)+'</th>' for t in topics)+'</tr></thead><tbody>'
 for m in matrix:body+='<tr><th><a href="#'+m['municipality']+'">'+e(m['municipality'].replace('-',' ').title())+'</a></th><td>'+str(m['routes'])+'</td><td>'+str(m['configuredFeeds'])+'</td>'+''.join('<td class="'+('gap' if not m['topics'][t] else '')+'">'+str(m['topics'][t])+'</td>' for t in topics)+'</tr>'
 body+='</tbody></table></div><p>* Met expliciete gemeentetoewijzing in de feedconfiguratie; provinciale feeds kunnen aanvullende berichten leveren.</p>'
 for m in matrix:
  local=[r for r in rows if m['municipality'] in r['municipalities']]
  body+='<details id="'+m['municipality']+'"><summary>'+e(m['municipality'].replace('-',' ').title())+' · '+str(len(local))+' geteste routes</summary><ul>'
  for r in local:body+='<li><a href="'+e(r['url'])+'">'+e(r['name'])+'</a><small>'+e(' · '.join(r['topics']))+' · '+e(r['crawlTest'])+'</small></li>'
  body+='</ul></details>'
 body+='<h2 id="feeds">Feed voor feed gecontroleerd</h2><p>Laatste inname: '+e(intake['runAt'])+'. Periode: '+e(' – '.join(intake['window']))+'. RSS kan oudere berichten al verwijderd hebben.</p><div class="table"><table><tr><th>Bron</th><th>Status</th><th>Ontvangen in periode</th><th>Nieuw</th></tr>'
 for s in feeds:
  r=results.get(s['id'],{});body+='<tr><td><a href="'+e(s['feed'])+'">'+e(s['name'])+'</a></td><td>'+e(r.get('status','nog niet in laatste run'))+'</td><td>'+e(r.get('receivedInWindow','—'))+'</td><td>'+e(r.get('added','—'))+'</td></tr>'
 body+='</table></div><h2>Bronfamilies naast nieuwsmedia</h2>'
 for f in read('source-families.json'):body+='<p><a href="'+e(f['url'])+'"><b>'+e(f['name'])+'</b></a> — '+e(f.get('state',''))+'<br>'+e(f.get('next',''))+'</p>'
 body+='<h2 id="developer">Van ophalen naar automatisch publiceren</h2><ol><li>Plan de bestaande run-once pipeline op de server. Begin met feeds elke 15 minuten, officiële publicaties en raadsstukken elk uur en archieven dagelijks. Dit zijn startwaarden, geen ingestelde scheduler.</li><li>Bewaar bronidentiteit, oorspronkelijke datum, ophaaltijd, wijzigingen en gemeentelijke dekking. Een clubfeed uit Woerden is geen provinciaal hoofdnieuws.</li><li>Voeg de schrijfservice toe: gecontroleerde feiten → eigen korte tekst → bronverwijzing direct bij artikel. Een herschreven titel is geen artikel.</li><li>Laat machinecontroles datum, plaats, duplicaten, vervallen meldingen en beeldrechten toetsen. Niet geslaagde berichten blijven geblokkeerd; menselijke namen niet willekeurig als auteur toewijzen.</li><li>Publiceer via Strapi pas nadat de productievelden, authenticatie en publicatiecontract zijn getest. Verwerk wijzigingen en intrekkingen ook op reeds gepubliceerde berichten.</li><li>Meet tijd bron → opgehaald → verwerkt → gepubliceerd, foutpercentage en dekking per gemeente. “Als eerste” is niet te garanderen.</li></ol><p><a href="developer-runbook.txt">Download uitvoerbare opdrachten en ontbrekende productiestappen</a></p>'
 css='body{font:16px/1.65 system-ui;color:#2C2C2C;max-width:1240px;margin:auto;padding:24px}header{background:#F5F1ED;padding:32px;border-top:6px solid #0072FF}h1{font-size:clamp(28px,4vw,44px);line-height:1.12}h2{margin-top:40px}a{color:#1050C2}nav{display:flex;flex-wrap:wrap;gap:16px;padding:24px 0}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:16px}.stats div{padding:20px;background:#F5F1ED}.stats strong{display:block;font-size:34px}.stats span{font-size:14px}.table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left;vertical-align:top}th{min-width:95px}.gap{background:#F5F1ED}details{padding:15px 0;border-bottom:1px solid #ddd}summary{cursor:pointer;font-weight:700}small{display:block;color:#555}li{margin:12px 0}'
 (out/'gemeenten.html').write_text('<!doctype html><html lang="nl"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta name="robots" content="noindex,nofollow"><title>PITO · bronnen per gemeente</title><style>'+css+'</style>'+body+'</html>')
 print(json.dumps({'routes':len(rows),'statuses':dict(counts),'feeds':len(feeds),'municipalities':len(matrix)}))
if __name__=='__main__':main()
